// Canonical LK read-only account API; desktop copy is generated by sync-lk-ide-presets.mjs.
const number = (value) =>
  typeof value === "number" && Number.isFinite(value) && value >= 0
    ? value
    : null;
const text = (value) =>
  typeof value === "string" ? value.slice(0, 256) : null;
const LK_MODEL_ALIASES = Object.freeze({
  "tt-6.1-sol": "gpt-6.1-sol",
  "tt-6-luna": "gpt-6.1-sol",
  "fb-5-2": "claude-opus-5-5",
  "gem-3.8-flash": "gemini-4-carbon",
});
const canonicalLkModel = (value) => {
  const model = typeof value === "string" ? value.trim() : "";
  return LK_MODEL_ALIASES[model] || model;
};
const counts = (row = {}) =>
  Object.fromEntries(
    [
      "cost",
      "count",
      "success_count",
      "failed_count",
      "refunded_count",
      "refunded_cost",
    ].map((key) => [key, number(row[key])]),
  );

/** Explicit schemas prevent upstream account metadata or credentials reaching UIs. */
function normalizeLkAccountPart(kind, data) {
  if (!data || typeof data !== "object" || Array.isArray(data))
    throw new Error("Invalid account response");
  if (kind === "balance") {
    if (number(data.balance) === null || data.unit !== "算力")
      throw new Error("Invalid balance response");
    const quota = data.api_key_quota || {};
    return {
      balance: number(data.balance),
      unit: "算力",
      quota: {
        used: number(quota.used),
        limit: number(quota.limit),
        remaining: quota.limit === 0 ? null : number(quota.remaining),
        unlimited: quota.limit === 0,
      },
    };
  }
  if (kind === "usage") {
    if (!Array.isArray(data.by_model) || data.unit !== "算力")
      throw new Error("Invalid usage response");
    return {
      from: text(data.from),
      to: text(data.to),
      unit: "算力",
      scope: text(data.scope),
      total: counts(data.grand_total),
      models: data.by_model.slice(0, 1000).map((row) => ({
        model: text(row.model),
        type: text(row.model_type),
        ...counts(row),
      })),
    };
  }
  if (kind === "records") {
    if (!Array.isArray(data.records) || data.unit !== "算力")
      throw new Error("Invalid billing response");
    return {
      total: number(data.total),
      limit: number(data.limit),
      offset: number(data.offset),
      rows: data.records.slice(0, 200).map((row) => ({
        taskId: text(String(row.task_id ?? "")),
        model: text(row.model),
        group: text(row.channel_group),
        state: text(row.state),
        cost: number(row.cost),
        refunded: row.refunded === true,
        refundedAmount: number(row.refunded_amount),
        createdAt: text(row.created_at),
        completedAt: text(row.completed_at),
      })),
    };
  }
  if (kind === "pricing") {
    if (!Array.isArray(data.channel_groups))
      throw new Error("Invalid pricing response");
    return {
      model: text(data.name),
      available:
        typeof data.available_for_this_key === "boolean"
          ? data.available_for_this_key
          : null,
      unit: "算力",
      tokenDivisor: 1000000,
      groups: data.channel_groups.slice(0, 200).map((row) => ({
        name: text(row.group_name),
        active: row.is_active === true,
        allowed:
          data.available_for_this_key !== false &&
          row.in_key_whitelist === true &&
          row.excluded_for_this_key !== true,
        billingMethod: text(row.billing_method),
        basePrice: number(row.base_price),
        inputPerMillion: number(row.input_token_price),
        outputPerMillion: number(row.output_token_price),
        discount: number(row.current_time_discount),
      })),
    };
  }
  throw new Error("Unknown account response");
}

async function getJson(fetchImpl, origin, path, apiKey) {
  const response = await fetchImpl(origin + path, {
    headers: { Authorization: `Bearer ${apiKey}`, Accept: "application/json" },
    signal: AbortSignal.timeout(12000),
    redirect: "error",
  });
  if (!response.ok) throw new Error("Account request failed");
  // Bound decoded bytes too; Content-Length may be absent or compressed.
  const reader = response.body.getReader();
  const chunks = [];
  let length = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      length += value.byteLength;
      if (length > 2 * 1024 * 1024)
        throw new Error("Account response too large");
      chunks.push(value);
    }
  } finally {
    await reader.cancel().catch(() => {});
  }
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}

/** Read-only, fresh account queries. No disk cache and no generic provider env keys. */
async function fetchLkAccount(
  connection,
  options = {},
  { fetcher = fetch } = {},
) {
  const days = Number(options.days ?? 1);
  const limit = Number(options.limit ?? 20);
  const offset = Number(options.offset ?? 0);
  const scope = options.scope ?? "key";
  if (
    !Number.isInteger(days) ||
    days < 1 ||
    days > 30 ||
    !Number.isInteger(limit) ||
    limit < 1 ||
    limit > 200 ||
    !Number.isSafeInteger(offset) ||
    offset < 0 ||
    !["key", "user"].includes(scope)
  )
    throw new Error(
      "Use days 1–30, limit 1–200, nonnegative offset and scope key/user",
    );
  if (
    !connection ||
    !/^https:\/\/api\.(?:vv666|lk666)\.ai\/(?:v1|v1beta)\/?$/.test(
      connection.baseUrl || "",
    ) ||
    !connection.apiKey
  )
    throw new Error("An LK connection with its own API key is required");
  const model = canonicalLkModel(options.model ?? connection.model);
  if (
    typeof model !== "string" ||
    !model.trim() ||
    model.length > 256 ||
    /[\r\n\0]/.test(model)
  )
    throw new Error("A valid pricing model is required");
  const origin = new URL(connection.baseUrl).origin;
  const query = new URLSearchParams({ days: String(days), scope });
  const requests = {
    balance: "/v1/skills/balance",
    usage: `/v1/skills/usage?${query}`,
    records: `/v1/skills/usage?${query}&detail=1&limit=${limit}&offset=${offset}`,
    pricing: `/v1/skills/models/${encodeURIComponent(model)}/pricing`,
  };
  const result = {
    channel: "lk",
    origin,
    model,
    days,
    scope,
    fetchedAt: new Date().toISOString(),
    unit: "算力",
    errors: {},
  };
  await Promise.all(
    Object.entries(requests).map(async ([kind, path]) => {
      try {
        result[kind] = normalizeLkAccountPart(
          kind,
          await getJson(fetcher, origin, path, connection.apiKey),
        );
      } catch {
        result[kind] = null;
        result.errors[kind] = "查询失败，请检查 Key 权限或稍后刷新";
      }
    }),
  );
  result.partial = Object.keys(result.errors).length > 0;
  return result;
}

function formatLkAccount(result) {
  const quota = result.balance?.quota;
  return [
    `LK 账户 · ${result.fetchedAt} · ${result.origin}`,
    `账户余额：${result.balance?.balance ?? "未知"} 算力`,
    `Key 已用：${quota?.used ?? "未知"}；剩余额度：${quota?.unlimited ? "不限额" : (quota?.remaining ?? "未知")} 算力`,
    `最近 ${result.days} 天 API ${result.scope === "user" ? "全部 Key" : "当前 Key"} 实扣：${result.usage?.total?.cost ?? "未知"} 算力`,
    `动态价格（${result.model}，算力/百万 Token）：`,
    ...(result.pricing?.available === false
      ? ["当前 Key 无此模型权限；价格仅供参考。"]
      : []),
    ...(result.pricing?.groups || []).map(
      (row) =>
        `  ${row.name}: ${row.billingMethod === "按token" ? `输入 ${row.inputPerMillion ?? "未知"} / 输出 ${row.outputPerMillion ?? "未知"}` : `基础价 ${row.basePrice ?? "未知"}`} · ${row.billingMethod} · ${row.active ? "启用" : "停用"} · ${row.allowed ? "Key 可用" : "Key 不可用"}`,
    ),
    "账单记录（平台实扣；运行中可能仍为预扣；退款已计入金额）：",
    ...(result.records?.rows || []).map(
      (row) =>
        `  ${row.taskId} ${row.model} ${row.state} ${row.cost ?? "未知"} 算力${row.refunded ? ` · 已退款 ${row.refundedAmount ?? "未知"}` : ""}`,
    ),
    `记录 ${result.records?.offset ?? 0} 起 / 共 ${result.records?.total ?? "未知"} 条；--offset 翻页。`,
    "价格含当前时段折扣；实际路由分组以账单为准。账单不返回 Token 数，不能自动对应本地单次请求。金额保留四位，小额显示 0 不代表免费。算力不自动折算充值现金成本。",
    ...Object.entries(result.errors || {}).map(
      ([kind, error]) => `${kind}: ${error}`,
    ),
  ].join("\n");
}

module.exports = { normalizeLkAccountPart, fetchLkAccount, formatLkAccount };
